                SilverScreen.Editor.EnvironmentArt.StageSchoolA1Review.Capture(camera, "a3_03_right", new UnityEngine.Vector3(40, 6, 3), new UnityEngine.Vector3(0, 3, 3), 43, true, 10.2f);
                SilverScreen.Editor.EnvironmentArt.StageSchoolA1Review.Capture(camera, "a3_04_rear", new UnityEngine.Vector3(0, 6, 44), new UnityEngine.Vector3(0, 3, 3), 43, true, 10.4f);
                shot("a3_09_reception", new UnityEngine.Vector3(2.6f, 2.2f, -7.1f), new UnityEngine.Vector3(0, 1, -4.2f), 70);
                shot("a3_17_reception_rear", new UnityEngine.Vector3(2, 2.2f, -1.95f), new UnityEngine.Vector3(0, .9f, -4.2f), 70);
                shot("a3_23_restrooms", new UnityEngine.Vector3(8.6f, 2.0f, -4.8f), new UnityEngine.Vector3(8.65f, 1.5f, -6.2f), 92);
