                shot("a32_cubicle_inside1", new UnityEngine.Vector3(9.15f, 1.65f, -7.6f), new UnityEngine.Vector3(9.5f, 1.40f, -6.2f), 72);
                shot("a3_19_staff_office", new UnityEngine.Vector3(-3.45f, 2.45f, 3.75f), new UnityEngine.Vector3(-5.5f, 1.3f, 6.4f), 85);
                var hidden = new System.Collections.Generic.List<UnityEngine.GameObject>();
                foreach (string path in new[]{"Roofs", "Ceilings", "Shell/Raised"})
                {
                    var t = root.transform.Find(path);
                    if (t != null && t.gameObject.activeSelf)
                    {
                        hidden.Add(t.gameObject);
                        t.gameObject.SetActive(false);
                    }
                }

                try
                {
                    SilverScreen.Editor.EnvironmentArt.StageSchoolA1Review.Capture(camera, "a32_staff_circulation", new UnityEngine.Vector3(-5.0f, 17, 5.899f), new UnityEngine.Vector3(-5, 0, 5.9f), 43, true, 3.6f);
                    SilverScreen.Editor.EnvironmentArt.StageSchoolA1Review.Capture(camera, "a32_fixed_table_routes", new UnityEngine.Vector3(0, 42, 2.999f), new UnityEngine.Vector3(0, 0, 3), 43, true, 14.7f);
                }
                finally
                {
                    foreach (var go in hidden)
                        go.SetActive(true);
                }
            }
            finally
            {
                camera.transform.SetPositionAndRotation(pos, rot);
                camera.fieldOfView = fov;
                camera.orthographic = orth;
                camera.orthographicSize = size;
            }

            result.Log("A3.2 sixteen targeted captures completed; camera and visibility restored.");
        }
    }
}",
    "result": "Command executed successfully."
  }
